// ── i18n translations ──────────────────────────────────────────────────────
// Every user-facing string in the app, organised by namespace.
// The `t()` function in I18nContext resolves `namespace.key` at runtime.
// Keep keys flat within each namespace — dot-separated paths are NOT nested.

export type TranslationKey = keyof typeof translations.en;

