  'terms.body1': 'Lyceum sử dụng nhiều mô hình AI (Gemini, Groq, NVIDIA, OpenRouter, Ollama...) để hỗ trợ học tập: đối thoại Socratic, chấm điểm, tạo bản đồ tri thức và trợ lý giọng nói ARI.',
