  'terms.heading': '이용약관',
  'terms.readBefore': '시작하기 전에 읽어주세요',
  'terms.body1': 'Lyceum은 여러 AI 모델(Gemini, Groq, NVIDIA, OpenRouter, Ollama...)을 사용하여 학습을 지원합니다: 소크라테스 대화, 채점, 지식 맵 생성, ARI 음성 비서.',
  'terms.body2': '업로드한 콘텐츠(노트, 과제, 이미지, 음성 녹음)는 처리를 위해 위의 AI 제공업체에 전송될 수 있습니다. 민감한 개인 정보나 공유할 권리가 없는 자료를 업로드하지 마세요.',
  'terms.body3': 'ARI(음성 비서)는 마이크가 켜져 있을 때 백그라운드에서 즉시 도움을 위해 청취할 수 있습니다 — ARI 아이콘 옆의 버튼으로 언제든 마이크를 음소거하거나 일시정지할 수 있습니다.',
  'terms.body4': '학습 데이터(노트, 오류, 진행률)는 브라우저에 저장되어 개인화된 경험을 제공합니다. Lyceum은 AI가 생성한 콘텐츠의 절대적인 정확성을 보장하지 않습니다 — 중요한 내용은 항상 다시 확인하세요.',
