  'terms.title': 'Willkommen bei The Lyceum',
  'terms.body': 'Bevor Sie beginnen, lesen Sie bitte unsere Nutzungsbedingungen. The Lyceum verwendet KI für sokratischen Dialog, Bewertung, Erstellung von Wissenskarten und den ARI-Sprachassistenten.',
  'terms.heading': 'Nutzungsbedingungen',
  'terms.readBefore': 'Bitte lesen Sie vor Beginn',
  'terms.body1': 'Lyceum verwendet mehrere KI-Modelle (Gemini, Groq, NVIDIA, OpenRouter, Ollama...) zur Unterstützung Ihres Studiums: sokratischer Dialog, Bewertung, Erstellung von Wissenskarten und der ARI-Sprachassistent.',
  'terms.body2': 'Von Ihnen hochgeladene Inhalte (Notizen, Aufgaben, Bilder, Sprachaufnahmen) können an die oben genannten KI-Anbieter zur Verarbeitung gesendet werden. Laden Sie keine sensiblen persönlichen Daten oder Material hoch, das Sie nicht weitergeben dürfen.',
  'terms.body3': 'ARI (der Sprachassistent) kann im Hintergrund zuhören, solange Ihr Mikrofon aktiv ist, um Ihnen sofort zu helfen — Sie können das Mikrofon jederzeit stummschalten oder pausieren über die Schaltflächen neben dem ARI-Symbol.',
  'terms.body4': 'Studien Daten (Notizen, Fehler, Fortschritt) werden in Ihrem Browser gespeichert, um Ihre Erfahrung zu personalisieren. Lyceum garantiert nicht die absolute Genauigkeit von KI-generierten Inhalten — überprüfen Sie immer alles Wichtige.',
  'terms.agreeContinue': 'Ich stimme zu, fortfahren',

