  'landing.step3Body': 'Он запоминается потому, что вы нашли его сами, а не потому, что вам сказали. Поэтому вы помните его и на экзамене.',
  'landing.featureSubtitle': 'Четыре инструмента, все работающие вместе в одном месте.',
  'landing.feature1LargeTitle': 'Практика объяснения своими словами',
  'landing.feature1LargeBody': 'Объясните то, что вы узнали, простыми словами. AI Lyceum замечает пробелы и задаёт ещё вопросы, чтобы вы действительно поняли — а не просто запомнили.',
  'landing.feature2SmallTitle': 'Карта знаний',
  'landing.feature2SmallBody': 'Каждая идея, которую вы изучаете, связывается с общей картой, как ветви дерева — чтобы вы всегда видели, как всё связано.',
  'landing.feature3SmallTitle': 'Банк ошибок',
  'landing.feature3SmallBody': 'Ваши ошибки сохраняются и сортируются. Lyceum возвращает их позже, чтобы вы могли практиковаться, пока не начнёте делать правильно.',
  'landing.feature4SmallTitle': 'Банк справочников',
  'landing.feature4SmallBody': 'Каждый источник и ответ, который вы проверяете, сохраняется и систематизируется — ваша личная библиотека, доступная в любое время.',
  'landing.footerCopy': 'назван в честь школы, основанной Аристотелем',

