  'terms.title': 'ยินดีต้อนรับสู่ The Lyceum',
  'terms.body': 'ก่อนเริ่มต้น กรุณาทบทวนข้อกำหนดของเรา The Lyceum ใช้ AI สำหรับการสนทนาแบบโซ克拉ติก การให้คะแนนงาน สร้างแผนที่ความรู้ และผู้ช่วยเสียง ARI',
  'terms.heading': 'ข้อกำหนดการใช้งาน',
  'terms.readBefore': 'กรุณาอ่านก่อนเริ่มต้น',
  'terms.body1': 'Lyceum ใช้โมเดล AI หลายตัว (Gemini, Groq, NVIDIA, OpenRouter, Ollama...) เพื่อสนับสนุนการเรียนของคุณ: การสนทนาแบบโซ克拉ติก การให้คะแนนงาน สร้างแผนที่ความรู้ และผู้ช่วยเสียง ARI',
  'terms.body2': 'เนื้อหาที่คุณอัปโหลด (บันทึก งาน รูปภาพ ไฟล์เสียง) อาจถูกส่งไปยังผู้ให้บริการ AI ที่ระบุข้างต้นเพื่อประมวลผล อย่าอัปโหลดข้อมูลส่วนตัวที่ละเอียดอ่อนหรือวัสดุที่คุณไม่มีสิทธิ์แชร์',
  'terms.body3': 'ARI (ผู้ช่วยเสียง) อาจฟังในเบื้องหลังขณะไมค์เปิดอยู่เพื่อช่วยคุณได้ทันที — คุณสามารถปิดไมค์หรือหยุดชั่วคราวได้ทุกเมื่อโดยใช้ปุ่มข้างไอคอน ARI',
  'terms.body4': 'ข้อมูลการเรียน (บันทึก ข้อผิดพลาด ความคืบหน้า) ถูกเก็บไว้ในเบราว์เซอร์เพื่อปรับแต่งประสบการณ์ Lyceum ไม่รับประกันความถูกต้องของเนื้อหาที่ AI สร้าง — ตรวจสอบข้อมูลสำคัญเสมอ',
  'terms.agreeContinue': 'ยอมรับ ดำเนินการต่อ',

