  'terms.title': 'The Lyceum में आपका स्वागत है',
  'terms.body': 'शुरू करने से पहले, कृपया हमारी शर्तें देखें। The Lyceum सोक्रेटिक संवाद, आपका मूल्यांकन, ज्ञान मानचित्र बनाने, और ARI वॉयस असिस्टेंट के लिए AI का उपयोग करता है।',
  'terms.heading': 'उपयोग की शर्तें',
  'terms.readBefore': 'शुरू करने से पहले कृपया पढ़ें',
  'terms.body1': 'Lyceum आपकी पढ़ाई में सहायता के लिए कई AI मॉडल (Gemini, Groq, NVIDIA, OpenRouter, Ollama...) का उपयोग करता है: सोक्रेटिक संवाद, कार्य मूल्यांकन, ज्ञान मानचित्र निर्माण, और ARI वॉयस असिस्टेंट।',
  'terms.body2': 'जो सामग्री आप अपलोड करते हैं (नोट्स, असाइनमेंट, चित्र, वॉयस रिकॉर्डिंग) उसे ऊपर सूचीबद्ध AI प्रदाताओं को प्रसंस्करण के लिए भेजा जा सकता है। संवेदनशील व्यक्तिगत जानकारी या साझा करने का अधिकार नहीं होने वाली सामग्री अपलोड न करें।',
  'terms.body3': 'ARI (वॉयस असिस्टेंट) आपके माइक चालू होने पर बैकग्राउंड में सुन सकता है ताकि आपको तुरंत मदद मिल सके — आप ARI आइकन के बगल में बटन से कभी भी माइक म्यूट या पॉज़ कर सकते हैं।',
  'terms.body4': 'अध्ययन डेटा (नोट्स, त्रुटियाँ, प्रगति) आपके ब्राउज़र में सहेजा जाता है ताकि आपका अनुभव व्यक्तिगत हो। Lyceum AI-जनित सामग्री की पूर्ण सटीकता की गारंटी नहीं देता — महत्वपूर्ण कुछ भी हमेशा दोबारा जाँचें।',
  'terms.agreeContinue': 'सहमत हूँ, जारी रखें',

