  'terms.title': 'مرحباً بك في The Lyceum',
  'terms.body': 'قبل البدء، راجع شروطنا. يستخدم Lyceum الـ AI للحوار السقراطي وتقييم عملك وإنشاء خرائط المعرفة ومساعد الصوت ARI.',
  'terms.heading': 'شروط الاستخدام',
  'terms.readBefore': 'يرجى القراءة قبل البدء',
  'terms.body1': 'يستخدم Lyceum نماذج AI متعددة (Gemini, Groq, NVIDIA, OpenRouter, Ollama...) لدعم دراستك: الحوار السقراطي، تقييم العمل، إنشاء خرائط المعرفة، ومساعد الصوت ARI.',
  'terms.body2': 'المحتوى الذي ترفعه (ملاحظات، واجبات، صور، تسجيلات صوتية) قد يُرسل لمزودي AI المدرجين أعلاه للمعالجة. لا ترفع معلومات شخصية حساسة أو مواد ليس لك حق مشاركتها.',
  'terms.body3': 'ARl (مساعد الصوت) قد يصغي في الخلفية بينما الميكروفون مفعّل لمساعدتك فوراً — يمكنك كتم الميكروفون أو الإيقاف المؤقت في أي وقت باستخدام الأزرار بجانب أيقونة ARI.',
  'terms.body4': 'بيانات الدراسة (ملاحظات، أخطاء، تقدم) تُخزن في متصفحك لتخصيص تجربتك. لا يضمن Lyceum الدقة المطلقة لمحتوى AI — تحقق دائماً من أي شيء مهم.',
  'terms.agreeContinue': 'أوافق، متابعة',

